import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static int lilysHomework(List<Integer> arr) {List<Integer> sorted = new ArrayList<>(arr);Collections.sort(sorted);List<Integer> reverseSorted = new ArrayList<>(sorted);Collections.reverse(reverseSorted);return Math.min(countSwaps(new ArrayList<>(arr), sorted), countSwaps(new ArrayList<>(arr), reverseSorted));}private static int countSwaps(List<Integer> arr, List<Integer> target) {Map<Integer, Integer> map = new HashMap<>();for (int i = 0; i < target.size(); i++) {map.put(target.get(i), i);}boolean[] visited = new boolean[arr.size()];int swaps = 0;for (int i = 0; i < arr.size(); i++) {if (visited[i] || arr.get(i).equals(target.get(i))) continue;int cycleSize = 0;int j = i;while (!visited[j]) {visited[j] = true;j = map.get(arr.get(j));cycleSize++;}if (cycleSize > 0) swaps += (cycleSize - 1);}return swaps;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));String output = System.getenv("OUTPUT_PATH");BufferedWriter bufferedWriter = output != null ? new BufferedWriter(new FileWriter(output)) : new BufferedWriter(new OutputStreamWriter(System.out));String line1 = bufferedReader.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());String line2 = bufferedReader.readLine();if (line2 == null) return;List<Integer> arr = Stream.of(line2.replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());int result = Result.lilysHomework(arr);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}